-- BEGIN SOURCE: beegame-supabase-invitations-migration.sql
-- BeeGame invitation gate migration.
-- Run after docs/beegame-supabase-schema.sql. This keeps the registration gate
-- inside Supabase using tables, RPC functions, and auth.users triggers.

create extension if not exists pgcrypto;

create table if not exists public.beegame_invitation_settings (
  id boolean primary key default true check (id),
  required boolean not null default false,
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

insert into public.beegame_invitation_settings (id, required)
values (true, false)
on conflict (id) do nothing;

create table if not exists public.beegame_invitations (
  id uuid primary key default gen_random_uuid(),
  code text,
  code_hash text not null unique,
  label text not null default 'Invitation',
  enabled boolean not null default true,
  max_uses integer check (max_uses is null or max_uses > 0),
  used_count integer not null default 0 check (used_count >= 0),
  expires_at timestamptz,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.beegame_invitation_redemptions (
  user_id uuid primary key references auth.users(id) on delete cascade,
  invitation_id uuid not null references public.beegame_invitations(id) on delete restrict,
  redeemed_at timestamptz not null default now()
);

alter table public.beegame_invitations
  add column if not exists code text;

create table if not exists public.beegame_oauth_invitation_nonces (
  nonce text primary key,
  invitation_id uuid not null references public.beegame_invitations(id) on delete cascade,
  expires_at timestamptz not null,
  consumed_by uuid references auth.users(id) on delete set null,
  consumed_at timestamptz,
  created_at timestamptz not null default now()
);

create or replace function public.beegame_invitation_code_hash(p_code text)
returns text
language sql
immutable
as $$
  select encode(extensions.digest(convert_to(trim(coalesce(p_code, '')), 'UTF8'), 'sha256'::text), 'hex')
$$;

create or replace function public.beegame_invitation_required()
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select coalesce((select required from public.beegame_invitation_settings where id = true), false)
$$;

create or replace function public.beegame_public_invitation_settings()
returns jsonb
language sql
security definer
set search_path = public
stable
as $$
  select jsonb_build_object('required', public.beegame_invitation_required())
$$;

create or replace function public.beegame_find_usable_invitation(p_code text)
returns uuid
language sql
security definer
set search_path = public
stable
as $$
  select i.id
  from public.beegame_invitations i
  where i.code_hash = public.beegame_invitation_code_hash(p_code)
    and i.enabled = true
    and (i.expires_at is null or i.expires_at > now())
    and (i.max_uses is null or i.used_count < i.max_uses)
  limit 1
$$;

create or replace function public.beegame_validate_invitation_code(p_code text)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select public.beegame_find_usable_invitation(p_code) is not null
$$;

create or replace function public.beegame_admin_list_invitations()
returns jsonb
language plpgsql
security definer
set search_path = public
stable
as $$
declare
  result jsonb;
begin
  if not public.beegame_is_platform_owner() then
    raise exception 'Forbidden';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', i.id,
    'code', i.code,
    'label', i.label,
    'enabled', i.enabled,
    'maxUses', i.max_uses,
    'usedCount', i.used_count,
    'expiresAt', i.expires_at,
    'createdBy', i.created_by,
    'createdAt', i.created_at,
    'updatedAt', i.updated_at
  ) order by i.created_at desc), '[]'::jsonb)
  into result
  from public.beegame_invitations i;

  return result;
end
$$;

create or replace function public.beegame_admin_save_invitation_settings(p_required boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.beegame_is_platform_owner() then
    raise exception 'Forbidden';
  end if;

  insert into public.beegame_invitation_settings (id, required, updated_by, updated_at)
  values (true, coalesce(p_required, false), auth.uid(), now())
  on conflict (id) do update
  set required = excluded.required,
      updated_by = excluded.updated_by,
      updated_at = now();

  return public.beegame_public_invitation_settings();
end
$$;

create or replace function public.beegame_admin_create_invitation(
  p_code text,
  p_label text default null,
  p_max_uses integer default null,
  p_expires_at timestamptz default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  created public.beegame_invitations%rowtype;
begin
  if not public.beegame_is_platform_owner() then
    raise exception 'Forbidden';
  end if;
  if nullif(trim(coalesce(p_code, '')), '') is null then
    raise exception 'Invitation code is required';
  end if;
  if p_max_uses is not null and p_max_uses < 1 then
    raise exception 'maxUses must be greater than zero';
  end if;

  insert into public.beegame_invitations (
    code,
    code_hash,
    label,
    max_uses,
    expires_at,
    created_by
  ) values (
    trim(p_code),
    public.beegame_invitation_code_hash(p_code),
    coalesce(nullif(trim(coalesce(p_label, '')), ''), trim(p_code)),
    p_max_uses,
    p_expires_at,
    auth.uid()
  )
  returning * into created;

  return jsonb_build_object(
    'id', created.id,
    'code', created.code,
    'label', created.label,
    'enabled', created.enabled,
    'maxUses', created.max_uses,
    'usedCount', created.used_count,
    'expiresAt', created.expires_at,
    'createdBy', created.created_by,
    'createdAt', created.created_at,
    'updatedAt', created.updated_at
  );
exception
  when unique_violation then
    raise exception 'Invitation code already exists';
end
$$;

create or replace function public.beegame_admin_update_invitation(
  p_id uuid,
  p_label text default null,
  p_enabled boolean default null,
  p_max_uses integer default null,
  p_clear_max_uses boolean default false,
  p_expires_at timestamptz default null,
  p_clear_expires_at boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  updated public.beegame_invitations%rowtype;
begin
  if not public.beegame_is_platform_owner() then
    raise exception 'Forbidden';
  end if;

  update public.beegame_invitations
  set label = coalesce(nullif(trim(coalesce(p_label, '')), ''), label),
      enabled = coalesce(p_enabled, enabled),
      max_uses = case when p_clear_max_uses then null else coalesce(p_max_uses, max_uses) end,
      expires_at = case when p_clear_expires_at then null else coalesce(p_expires_at, expires_at) end,
      updated_at = now()
  where id = p_id
  returning * into updated;

  if updated.id is null then
    raise exception 'Invitation not found';
  end if;

  return jsonb_build_object(
    'id', updated.id,
    'code', updated.code,
    'label', updated.label,
    'enabled', updated.enabled,
    'maxUses', updated.max_uses,
    'usedCount', updated.used_count,
    'expiresAt', updated.expires_at,
    'createdBy', updated.created_by,
    'createdAt', updated.created_at,
    'updatedAt', updated.updated_at
  );
end
$$;

create or replace function public.beegame_admin_delete_invitation(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  deleted_count integer;
begin
  if not public.beegame_is_platform_owner() then
    raise exception 'Forbidden';
  end if;

  delete from public.beegame_invitations
  where id = p_id
    and not exists (
      select 1 from public.beegame_invitation_redemptions r
      where r.invitation_id = p_id
    );
  get diagnostics deleted_count = row_count;
  return jsonb_build_object('deleted', deleted_count > 0);
end
$$;

create or replace function public.beegame_redeem_invitation_for_user(
  p_user_id uuid,
  p_code text default null,
  p_invitation_id uuid default null
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  target_invitation public.beegame_invitations%rowtype;
begin
  if p_user_id is null then
    return false;
  end if;
  if exists (select 1 from public.beegame_invitation_redemptions where user_id = p_user_id) then
    return true;
  end if;

  select *
  into target_invitation
  from public.beegame_invitations i
  where (p_invitation_id is not null and i.id = p_invitation_id)
     or (p_invitation_id is null and i.code_hash = public.beegame_invitation_code_hash(p_code))
  for update;

  if target_invitation.id is null then
    return false;
  end if;
  if not target_invitation.enabled then
    return false;
  end if;
  if target_invitation.expires_at is not null and target_invitation.expires_at <= now() then
    return false;
  end if;
  if target_invitation.max_uses is not null and target_invitation.used_count >= target_invitation.max_uses then
    return false;
  end if;

  update public.beegame_invitations
  set used_count = used_count + 1,
      updated_at = now()
  where id = target_invitation.id;

  insert into public.beegame_invitation_redemptions (user_id, invitation_id)
  values (p_user_id, target_invitation.id)
  on conflict (user_id) do nothing;

  return true;
end
$$;

create or replace function public.beegame_create_oauth_invitation_nonce(p_code text)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  invitation_id uuid;
  nonce text;
begin
  invitation_id := public.beegame_find_usable_invitation(p_code);
  if invitation_id is null then
    raise exception 'Invalid invitation code';
  end if;

  nonce := encode(gen_random_bytes(24), 'hex');
  insert into public.beegame_oauth_invitation_nonces (nonce, invitation_id, expires_at)
  values (nonce, invitation_id, now() + interval '10 minutes');
  return nonce;
end
$$;

create or replace function public.beegame_redeem_oauth_invitation(p_nonce text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  current_user_id uuid;
  current_account_id uuid;
  nonce_row public.beegame_oauth_invitation_nonces%rowtype;
begin
  current_user_id := auth.uid();
  if current_user_id is null then
    raise exception 'Authentication required';
  end if;
  current_account_id := public.beegame_account_id(current_user_id);

  select *
  into nonce_row
  from public.beegame_oauth_invitation_nonces
  where nonce = nullif(trim(coalesce(p_nonce, '')), '')
  for update;

  if nonce_row.nonce is null or nonce_row.expires_at <= now() or nonce_row.consumed_at is not null then
    raise exception 'Invalid invitation nonce';
  end if;

  if not public.beegame_redeem_invitation_for_user(current_user_id, null, nonce_row.invitation_id) then
    raise exception 'Invalid invitation code';
  end if;

  update public.beegame_oauth_invitation_nonces
  set consumed_by = current_user_id,
      consumed_at = now()
  where nonce = nonce_row.nonce;

  update auth.users
  set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) ||
    jsonb_build_object('beegame_invitation_redeemed_at', now())
  where id = current_user_id;

  return jsonb_build_object('ok', true);
end
$$;

create or replace function public.beegame_user_has_invitation(p_user_id uuid)
returns boolean
language sql
security definer
set search_path = public
stable
as $$
  select exists (
    select 1 from public.beegame_invitation_redemptions r
    where r.user_id = p_user_id
  )
$$;

create or replace function public.beegame_handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  created_workspace_id uuid;
  canonical_account_id uuid;
  profile_name text;
  profile_avatar_url text;
  initial_role text;
  invited_platform_owner boolean;
begin
  invited_platform_owner := exists (
    select 1
    from public.beegame_platform_owner_invites i
    where lower(i.email) = lower(new.email)
      and (i.claimed_user_id is null or i.claimed_user_id = new.id)
  );

  if public.beegame_invitation_required()
     and not invited_platform_owner
     and coalesce(new.raw_app_meta_data->>'beegame_role', '') <> 'owner'
     and not public.beegame_user_has_invitation(new.id) then
    if nullif(new.raw_user_meta_data->>'beegame_invitation_code', '') is not null then
      if not public.beegame_redeem_invitation_for_user(
        new.id,
        new.raw_user_meta_data->>'beegame_invitation_code',
        null
      ) then
        raise exception 'Invalid invitation code';
      end if;
    elsif coalesce(new.raw_app_meta_data->>'provider', 'email') = 'email' then
      raise exception 'Invitation code is required';
    end if;
  end if;
  profile_name := coalesce(
    nullif(new.raw_user_meta_data->>'display_name', ''),
    nullif(new.raw_user_meta_data->>'full_name', ''),
    nullif(new.raw_user_meta_data->>'name', ''),
    nullif(new.raw_user_meta_data->>'user_name', ''),
    nullif(split_part(new.email, '@', 1), '')
  );
  profile_avatar_url := coalesce(
    nullif(new.raw_user_meta_data->>'avatar_url', ''),
    nullif(new.raw_user_meta_data->>'picture', ''),
    nullif(new.raw_user_meta_data->>'image', ''),
    nullif(new.raw_user_meta_data->>'photo_url', '')
  );
  initial_role := case
    when new.raw_app_meta_data->>'beegame_role' = 'owner' or invited_platform_owner then 'owner'
    else 'developer'
  end;
  canonical_account_id := new.id;
  if nullif(new.email, '') is not null and new.email_confirmed_at is not null then
    select l.account_id
    into canonical_account_id
    from public.beegame_account_links l
    where lower(l.email) = lower(new.email)
    order by
      case when l.account_id = l.user_id then 0 else 1 end,
      l.updated_at asc,
      l.account_id::text asc
    limit 1;
    canonical_account_id := coalesce(canonical_account_id, new.id);
  end if;

  insert into public.beegame_account_links (user_id, account_id, email)
  values (new.id, canonical_account_id, coalesce(new.email, new.id::text))
  on conflict (user_id) do update
  set account_id = excluded.account_id,
      email = excluded.email,
      updated_at = now();

  insert into public.beegame_profiles (user_id, display_name, email, avatar_url)
  values (new.id, profile_name, new.email, profile_avatar_url)
  on conflict (user_id) do update
  set display_name = coalesce(public.beegame_profiles.display_name, excluded.display_name),
      email = coalesce(excluded.email, public.beegame_profiles.email),
      avatar_url = coalesce(public.beegame_profiles.avatar_url, excluded.avatar_url),
      updated_at = now();

  insert into public.beegame_workspaces (name, owner_id)
  values (
    coalesce(profile_name, 'BeeGame Workspace'),
    new.id
  )
  on conflict (owner_id) do update
  set updated_at = now()
  returning id into created_workspace_id;

  insert into public.beegame_workspace_members (workspace_id, user_id, role)
  values (created_workspace_id, new.id, initial_role)
  on conflict (workspace_id, user_id) do update
  set role = case
    when new.raw_app_meta_data->>'beegame_role' = 'owner' or invited_platform_owner then 'owner'
    else excluded.role
  end;

  if invited_platform_owner then
    update public.beegame_platform_owner_invites
    set claimed_user_id = new.id,
        claimed_at = coalesce(claimed_at, now())
    where lower(email) = lower(new.email)
      and (claimed_user_id is null or claimed_user_id = new.id);
  end if;

  return new;
end
$$;

drop trigger if exists beegame_after_auth_user_created on auth.users;
create trigger beegame_after_auth_user_created
  after insert or update of email, email_confirmed_at, raw_user_meta_data, raw_app_meta_data on auth.users
  for each row execute function public.beegame_handle_new_user();

alter table public.beegame_invitation_settings enable row level security;
alter table public.beegame_invitations enable row level security;
alter table public.beegame_invitation_redemptions enable row level security;
alter table public.beegame_oauth_invitation_nonces enable row level security;

drop policy if exists "invitation settings platform owner access" on public.beegame_invitation_settings;
create policy "invitation settings platform owner access" on public.beegame_invitation_settings
  for all using (public.beegame_is_platform_owner())
  with check (public.beegame_is_platform_owner());

drop policy if exists "invitation platform owner access" on public.beegame_invitations;
create policy "invitation platform owner access" on public.beegame_invitations
  for all using (public.beegame_is_platform_owner())
  with check (public.beegame_is_platform_owner());

drop policy if exists "invitation redemption owner read" on public.beegame_invitation_redemptions;
create policy "invitation redemption owner read" on public.beegame_invitation_redemptions
  for select using (user_id = auth.uid() or public.beegame_is_platform_owner());

drop policy if exists "oauth invitation nonce platform owner read" on public.beegame_oauth_invitation_nonces;
create policy "oauth invitation nonce platform owner read" on public.beegame_oauth_invitation_nonces
  for select using (public.beegame_is_platform_owner());

revoke execute on function public.beegame_public_invitation_settings() from public;
grant execute on function public.beegame_public_invitation_settings() to anon, authenticated;

revoke execute on function public.beegame_validate_invitation_code(text) from public;
grant execute on function public.beegame_validate_invitation_code(text) to anon, authenticated;

revoke execute on function public.beegame_create_oauth_invitation_nonce(text) from public;
grant execute on function public.beegame_create_oauth_invitation_nonce(text) to anon, authenticated;

revoke execute on function public.beegame_redeem_oauth_invitation(text) from public;
grant execute on function public.beegame_redeem_oauth_invitation(text) to authenticated;

revoke execute on function public.beegame_admin_list_invitations() from public;
revoke execute on function public.beegame_admin_save_invitation_settings(boolean) from public;
revoke execute on function public.beegame_admin_create_invitation(text,text,integer,timestamptz) from public;
revoke execute on function public.beegame_admin_update_invitation(uuid,text,boolean,integer,boolean,timestamptz,boolean) from public;
revoke execute on function public.beegame_admin_delete_invitation(uuid) from public;
grant execute on function public.beegame_admin_list_invitations() to authenticated;
grant execute on function public.beegame_admin_save_invitation_settings(boolean) to authenticated;
grant execute on function public.beegame_admin_create_invitation(text,text,integer,timestamptz) to authenticated;
grant execute on function public.beegame_admin_update_invitation(uuid,text,boolean,integer,boolean,timestamptz,boolean) to authenticated;
grant execute on function public.beegame_admin_delete_invitation(uuid) to authenticated;
-- END SOURCE: beegame-supabase-invitations-migration.sql

-- BEGIN SOURCE: beegame-oauth-user-provisioning-repair.sql
-- Repair OAuth accounts created before the BeeGame workspace provisioning
-- trigger was installed. Safe to run repeatedly in the Supabase SQL editor.
--
-- Prerequisite: docs/beegame-supabase-schema.sql (or its equivalent) has
-- already created public.beegame_handle_new_user and the auth trigger.
-- This deliberately targets non-email identities only; email accounts still
-- follow the invitation policy enforced by the normal provisioning trigger.

do $$
begin
  if not exists (
    select 1
    from pg_trigger trigger_row
    join pg_proc procedure_row on procedure_row.oid = trigger_row.tgfoid
    join pg_namespace namespace_row on namespace_row.oid = procedure_row.pronamespace
    where trigger_row.tgrelid = 'auth.users'::regclass
      and trigger_row.tgname = 'beegame_after_auth_user_created'
      and namespace_row.nspname = 'public'
      and procedure_row.proname = 'beegame_handle_new_user'
  ) then
    raise exception 'BeeGame OAuth provisioning trigger is missing; apply docs/beegame-supabase-schema.sql first';
  end if;
end
$$;

-- The trigger creates the profile, account link, workspace, developer member
-- role. Updating the JSON value to itself intentionally
-- invokes the existing secure trigger without granting browser clients any
-- provisioning privilege.
update auth.users as auth_user
set raw_user_meta_data = coalesce(auth_user.raw_user_meta_data, '{}'::jsonb)
where coalesce(auth_user.raw_app_meta_data ->> 'provider', 'email') <> 'email'
  and not exists (
    select 1
    from public.beegame_workspace_members as member
    where member.user_id = auth_user.id
  );

-- Verify: each OAuth user should now have a workspace role. A normal account
-- should be `developer`; only explicitly configured platform owners are owner.
select
  auth_user.id,
  auth_user.email,
  member.role,
  workspace.id as workspace_id
from auth.users as auth_user
left join public.beegame_workspace_members as member
  on member.user_id = auth_user.id
left join public.beegame_workspaces as workspace
  on workspace.id = member.workspace_id
where coalesce(auth_user.raw_app_meta_data ->> 'provider', 'email') <> 'email'
order by auth_user.created_at;
-- END SOURCE: beegame-oauth-user-provisioning-repair.sql

-- BEGIN SOURCE: beegame-resource-authoring-migration.sql
-- Incremental migration for Pack authoring. Safe to run after the base BeeGame schema.

create table if not exists public.beegame_resource_folders (
  id text primary key,
  pack_id text not null references public.beegame_resource_packs(id) on delete cascade,
  name text not null,
  parent_id text references public.beegame_resource_folders(id) on delete cascade,
  path text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (pack_id, path)
);

create index if not exists beegame_resource_folders_pack_parent_idx
  on public.beegame_resource_folders (pack_id, parent_id, path);

alter table public.beegame_resource_folders enable row level security;
drop policy if exists "resource folder platform owner access" on public.beegame_resource_folders;
create policy "resource folder platform owner access" on public.beegame_resource_folders
  for all using (public.beegame_is_platform_owner())
  with check (public.beegame_is_platform_owner());

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_status_check;
alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_status_check
  check (status in ('queued', 'uploading', 'ready', 'failed', 'hidden', 'archived'));

-- Keep the Pack summary authoritative for all insertion, deletion, and future
-- cross-Pack moves. The trigger makes count maintenance transactional instead
-- of relying on any individual HTTP handler to race a read-modify-write update.
create or replace function public.beegame_sync_resource_pack_element_count()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op <> 'INSERT' then
    update public.beegame_resource_packs
    set element_count = (select count(*) from public.beegame_resource_elements where pack_id = old.pack_id),
        updated_at = now()
    where id = old.pack_id;
  end if;

  if tg_op <> 'DELETE' then
    update public.beegame_resource_packs
    set element_count = (select count(*) from public.beegame_resource_elements where pack_id = new.pack_id),
        updated_at = now()
    where id = new.pack_id;
  end if;

  return null;
end;
$$;

drop trigger if exists beegame_resource_elements_sync_pack_count on public.beegame_resource_elements;
create trigger beegame_resource_elements_sync_pack_count
after insert or delete or update of pack_id on public.beegame_resource_elements
for each row execute function public.beegame_sync_resource_pack_element_count();
-- END SOURCE: beegame-resource-authoring-migration.sql

-- BEGIN SOURCE: beegame-resource-typed-assets-migration.sql
-- Platform-neutral logical-asset identity, inspected contents and external relations.
-- Existing rows remain valid; administrators can classify them incrementally.

alter table public.beegame_resource_elements
  add column if not exists asset_kind text,
  add column if not exists capabilities text[] not null default '{}',
  add column if not exists content_profile jsonb,
  add column if not exists relations jsonb not null default '[]'::jsonb;

-- Preserve values from the superseded mixed ontology without guessing a new
-- technical type. Administrators can reclassify them from the recorded fact.
update public.beegame_resource_elements
set specs = jsonb_set(specs, '{legacyAssetKind}', to_jsonb(asset_kind), true),
    asset_kind = null
where asset_kind in ('character', 'prop', 'environment-module', 'prefab', 'ui-component', 'ui-kit');

-- The existing file kind is an objective technical fact, so these mappings do
-- not infer subject matter from names or folders. Ambiguous kinds remain null.
update public.beegame_resource_elements
set asset_kind = case kind
  when 'model' then 'model'
  when 'audio' then 'audio-clip'
  when 'font' then 'font'
  when 'image' then 'image'
  when 'material' then 'material'
  when 'sprite' then 'sprite'
  else null
end
where asset_kind is null
  and kind in ('model', 'audio', 'font', 'image', 'material', 'sprite');

update public.beegame_resource_elements
set specs = jsonb_set(specs, '{legacyRootCapabilities}', to_jsonb(
      array(select unnest(capabilities) intersect select unnest(array['root-motion', 'loopable', 'retargetable']::text[]))
    ), true),
    capabilities = array(select unnest(capabilities) except select unnest(array['root-motion', 'loopable', 'retargetable']::text[]))
where capabilities && array['root-motion', 'loopable', 'retargetable']::text[];

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_asset_kind_check;

alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_asset_kind_check
  check (asset_kind is null or asset_kind in (
    'image', 'texture', 'sprite', 'sprite-sheet', 'sprite-atlas',
    'frame-animation', 'tileset', 'tilemap',
    'mesh', 'model', 'scene', 'material', 'rig', 'animation-clip', 'animation-library',
    'ui-document', 'ui-screen',
    'font', 'audio-clip', 'audio-cue', 'audio-bank', 'music', 'ambience', 'voice',
    'vfx', 'shader', 'physical-material', 'collider', 'input-profile', 'data'
  ));

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_capabilities_check;

alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_capabilities_check
  check (capabilities <@ array[
    'alpha', 'tileable', 'nine-slice', 'sprite-slicing', 'frame-sequence',
    'atlas-regions', 'tile-collision',
    'skinned', 'rigged', 'contains-animations', 'contains-materials',
    'contains-textures', 'morph-targets',
    'lod', 'collision', 'navigation', 'modular', 'connection-points',
    'scene-layout', 'spawn-markers', 'objective-markers',
    'ui-states', 'focus-navigation', 'safe-area',
    'particle', 'flipbook', 'trail',
    'spatial-audio', 'loop-points', 'audio-variants',
    'physical-properties', 'ragdoll',
    'input-actions', 'touch-controls', 'gamepad-controls'
  ]::text[]);

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_content_profile_check;

alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_content_profile_check
  check (
    content_profile is null or (
      jsonb_typeof(content_profile) = 'object'
      and content_profile ?& array['packaging', 'components', 'inspection']
      and content_profile->>'packaging' in ('self-contained', 'external-dependencies', 'unknown')
      and jsonb_typeof(content_profile->'components') = 'array'
      and jsonb_typeof(content_profile->'inspection') = 'object'
      and content_profile->'inspection' ?& array['status', 'source']
      and content_profile->'inspection'->>'status' in ('complete', 'partial', 'unavailable')
      and content_profile->'inspection'->>'source' in ('server', 'client', 'admin')
    )
  );

create or replace function public.beegame_valid_resource_relations(value jsonb)
returns boolean
language sql
immutable
as $$
  select jsonb_typeof(value) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(value) relation
      where jsonb_typeof(relation) <> 'object'
         or coalesce(relation->>'kind', '') not in (
           'uses-texture', 'uses-material', 'uses-rig', 'animation-for',
           'collision-for', 'lod-of', 'variant-of', 'component-of',
           'audio-for', 'vfx-for'
         )
         or coalesce(relation->>'targetElementId', '') = ''
         or (relation ? 'role' and coalesce(relation->>'role', '') = '')
         or (relation ? 'required' and jsonb_typeof(relation->'required') <> 'boolean')
    );
$$;

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_relations_check;

alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_relations_check
  check (public.beegame_valid_resource_relations(relations));

create index if not exists beegame_resource_elements_asset_kind_idx
  on public.beegame_resource_elements (pack_id, asset_kind);

create index if not exists beegame_resource_elements_capabilities_idx
  on public.beegame_resource_elements using gin (capabilities);

create index if not exists beegame_resource_elements_relations_idx
  on public.beegame_resource_elements using gin (relations);
-- END SOURCE: beegame-resource-typed-assets-migration.sql

-- BEGIN SOURCE: beegame-resource-logical-asset-backfill.sql
-- Run only when beegame-resource-typed-assets-migration.sql was already
-- applied before its objective technical-kind backfill was added.
--
-- This migration does not classify characters, weapons, environments,
-- animation purposes, styles, or other semantic meaning. It maps only the
-- existing technical `kind` field and leaves ambiguous rows for Admin review.

update public.beegame_resource_elements
set asset_kind = case kind
  when 'model' then 'model'
  when 'audio' then 'audio-clip'
  when 'font' then 'font'
  when 'image' then 'image'
  when 'material' then 'material'
  when 'sprite' then 'sprite'
  else null
end
where asset_kind is null
  and kind in ('model', 'audio', 'font', 'image', 'material', 'sprite');
-- END SOURCE: beegame-resource-logical-asset-backfill.sql

-- BEGIN SOURCE: beegame-resource-dependency-bindings-migration.sql
-- Explicit external-file dependency mappings for Resource Pack elements.
-- A mapping preserves the URI embedded in a model/material and resolves it to
-- a Pack element ID. The workflow copier uses this to recreate the required
-- relative file layout in a target project.

alter table public.beegame_resource_elements
  add column if not exists dependency_bindings jsonb not null default '[]'::jsonb;

alter table public.beegame_resource_elements
  drop constraint if exists beegame_resource_elements_dependency_bindings_check;

create or replace function public.beegame_valid_dependency_bindings(value jsonb)
returns boolean
language sql
immutable
as $$
  select jsonb_typeof(value) = 'array'
    and not exists (
      select 1
      from jsonb_array_elements(value) binding
      where jsonb_typeof(binding) <> 'object'
         or coalesce(binding->>'referencePath', '') = ''
         or left(binding->>'referencePath', 1) = '/'
         or position('\\' in coalesce(binding->>'referencePath', '')) > 0
         or coalesce(binding->>'dependencyElementId', '') = ''
    );
$$;

alter table public.beegame_resource_elements
  add constraint beegame_resource_elements_dependency_bindings_check
  check (public.beegame_valid_dependency_bindings(dependency_bindings));

create index if not exists beegame_resource_elements_dependency_bindings_idx
  on public.beegame_resource_elements using gin (dependency_bindings);
-- END SOURCE: beegame-resource-dependency-bindings-migration.sql

-- BEGIN SOURCE: beegame-resource-governance-migration.sql
-- Resource library governance. Apply after beegame-supabase-schema.sql and
-- beegame-resource-authoring-migration.sql.

alter table public.beegame_resource_packs
  add column if not exists created_by uuid references auth.users(id) on delete set null,
  add column if not exists archived_at timestamptz;

create index if not exists beegame_resource_packs_created_by_idx
  on public.beegame_resource_packs (created_by, status, updated_at desc);

create table if not exists public.beegame_resource_audit_events (
  id uuid primary key default gen_random_uuid(),
  actor_id uuid references auth.users(id) on delete set null,
  pack_id text references public.beegame_resource_packs(id) on delete set null,
  element_id text references public.beegame_resource_elements(id) on delete set null,
  action text not null,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

create index if not exists beegame_resource_audit_events_pack_created_idx
  on public.beegame_resource_audit_events (pack_id, created_at desc);

alter table public.beegame_resource_audit_events enable row level security;

drop policy if exists "resource audit platform owner read" on public.beegame_resource_audit_events;
create policy "resource audit platform owner read" on public.beegame_resource_audit_events
  for select using (public.beegame_is_platform_owner());

-- The resource API writes through service-role credentials after resolving the
-- caller server-side. Direct browser writes remain denied by RLS.
revoke insert, update, delete on public.beegame_resource_audit_events from anon, authenticated;
-- END SOURCE: beegame-resource-governance-migration.sql

-- BEGIN SOURCE: beegame-resource-metadata-migration.sql
-- Resource metadata for governance and structured discovery. Apply after
-- beegame-resource-governance-migration.sql.

alter table public.beegame_resource_packs
  add column if not exists description text,
  add column if not exists tags text[] not null default '{}',
  add column if not exists source text,
  add column if not exists author text,
  add column if not exists license_evidence text,
  add column if not exists compatible_engines text[] not null default '{}',
  add column if not exists deprecated_at timestamptz;

create index if not exists beegame_resource_packs_tags_idx
  on public.beegame_resource_packs using gin (tags);

create index if not exists beegame_resource_packs_compatible_engines_idx
  on public.beegame_resource_packs using gin (compatible_engines);
-- END SOURCE: beegame-resource-metadata-migration.sql

-- BEGIN SOURCE: beegame-resource-ownership-rls-migration.sql
-- Resource-library ownership boundaries. Apply after
-- beegame-resource-governance-migration.sql.
--
-- Service-role writes bypass RLS; this policy protects direct authenticated
-- access to a Pack's Supabase metadata. Resource bytes are stored only in R2.

create or replace function public.beegame_can_manage_resource_pack(target_pack_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.beegame_is_platform_owner()
      or exists (
        select 1 from public.beegame_resource_packs pack
        where pack.id = target_pack_id and pack.created_by = auth.uid()
      );
$$;

revoke execute on function public.beegame_can_manage_resource_pack(text) from public;
grant execute on function public.beegame_can_manage_resource_pack(text) to authenticated;

alter table public.beegame_resource_packs enable row level security;
alter table public.beegame_resource_elements enable row level security;
alter table public.beegame_resource_folders enable row level security;

drop policy if exists "resource Pack platform owner access" on public.beegame_resource_packs;
drop policy if exists "resource Pack owner access" on public.beegame_resource_packs;
create policy "resource Pack owner access" on public.beegame_resource_packs
  for all using (public.beegame_is_platform_owner() or created_by = auth.uid())
  with check (public.beegame_is_platform_owner() or created_by = auth.uid());

drop policy if exists "resource element platform owner access" on public.beegame_resource_elements;
drop policy if exists "resource element owner access" on public.beegame_resource_elements;
create policy "resource element owner access" on public.beegame_resource_elements
  for all using (public.beegame_can_manage_resource_pack(pack_id))
  with check (public.beegame_can_manage_resource_pack(pack_id));

drop policy if exists "resource folder platform owner access" on public.beegame_resource_folders;
drop policy if exists "resource folder owner access" on public.beegame_resource_folders;
create policy "resource folder owner access" on public.beegame_resource_folders
  for all using (public.beegame_can_manage_resource_pack(pack_id))
  with check (public.beegame_can_manage_resource_pack(pack_id));

drop policy if exists "resource dependency platform owner access" on public.beegame_resource_dependencies;
drop policy if exists "resource dependency owner access" on public.beegame_resource_dependencies;
create policy "resource dependency owner access" on public.beegame_resource_dependencies
  for all using (
    exists (select 1 from public.beegame_resource_elements element where element.id = element_id and public.beegame_can_manage_resource_pack(element.pack_id))
  ) with check (
    exists (select 1 from public.beegame_resource_elements element where element.id = element_id and public.beegame_can_manage_resource_pack(element.pack_id))
  );

drop policy if exists "beegame resource pack platform read" on storage.objects;
drop policy if exists "beegame resource pack platform write" on storage.objects;
drop policy if exists "beegame resource pack owner access" on storage.objects;
-- END SOURCE: beegame-resource-ownership-rls-migration.sql

-- BEGIN SOURCE: beegame-storage-r2-foundation-migration.sql
-- BeeGame project-domain object storage foundation.
--
-- This migration does not alter existing Supabase Storage buckets, objects or
-- policies. New R2-backed business paths opt in by storing storage_object_id;
-- existing paths remain valid legacy locators during migration.

create table if not exists public.beegame_storage_objects (
  id uuid primary key default gen_random_uuid(),
  scope_type text not null check (scope_type in ('user', 'studio', 'platform', 'project', 'pack', 'deployment', 'session')),
  scope_id text not null,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  project_id text references public.beegame_projects(id) on delete cascade,
  pack_id text references public.beegame_resource_packs(id) on delete cascade,
  deployment_id text references public.beegame_deployments(id) on delete cascade,
  session_id text references public.beegame_sessions(id) on delete cascade,
  provider text not null check (provider in ('supabase', 'r2')),
  bucket_role text check (bucket_role in ('project-private', 'resource-private', 'delivery', 'log-private')),
  bucket text not null,
  object_key text not null,
  logical_path text,
  original_filename text,
  mime_type text,
  byte_size bigint check (byte_size is null or byte_size >= 0),
  checksum_algorithm text,
  checksum_value text,
  etag text,
  object_kind text not null,
  version_id text,
  status text not null default 'pending' check (status in ('pending', 'uploading', 'verifying', 'ready', 'failed', 'deleted')),
  visibility text not null default 'private' check (visibility in ('private', 'project', 'organization', 'public')),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint beegame_storage_objects_checksum_pair check (
    (checksum_algorithm is null and checksum_value is null)
    or (nullif(btrim(checksum_algorithm), '') is not null and nullif(btrim(checksum_value), '') is not null)
  ),
  constraint beegame_storage_objects_r2_role check (
    provider <> 'r2' or bucket_role is not null
  )
);

create unique index if not exists beegame_storage_objects_live_locator_idx
  on public.beegame_storage_objects (provider, bucket, object_key)
  where deleted_at is null;

create index if not exists beegame_storage_objects_owner_scope_idx
  on public.beegame_storage_objects (owner_user_id, scope_type, scope_id, created_at desc);

create index if not exists beegame_storage_objects_project_idx
  on public.beegame_storage_objects (project_id, status, object_kind)
  where project_id is not null and deleted_at is null;

create index if not exists beegame_storage_objects_pack_idx
  on public.beegame_storage_objects (pack_id, status, object_kind)
  where pack_id is not null and deleted_at is null;

create table if not exists public.beegame_storage_upload_intents (
  id uuid primary key default gen_random_uuid(),
  storage_object_id uuid not null references public.beegame_storage_objects(id) on delete cascade,
  owner_user_id uuid not null references auth.users(id) on delete cascade,
  upload_mode text not null default 'single' check (upload_mode in ('single', 'multipart')),
  multipart_upload_id text,
  idempotency_key text not null,
  expected_byte_size bigint check (expected_byte_size is null or expected_byte_size >= 0),
  expected_mime_type text,
  expected_checksum_algorithm text,
  expected_checksum_value text,
  status text not null default 'pending' check (status in ('pending', 'uploading', 'verifying', 'completed', 'failed', 'aborted', 'expired')),
  expires_at timestamptz not null,
  completed_at timestamptz,
  last_error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint beegame_storage_upload_intents_checksum_pair check (
    (expected_checksum_algorithm is null and expected_checksum_value is null)
    or (nullif(btrim(expected_checksum_algorithm), '') is not null and nullif(btrim(expected_checksum_value), '') is not null)
  ),
  constraint beegame_storage_upload_intents_multipart_id check (
    upload_mode = 'multipart' or multipart_upload_id is null
  )
);

create unique index if not exists beegame_storage_upload_intents_idempotency_idx
  on public.beegame_storage_upload_intents (owner_user_id, idempotency_key);

create index if not exists beegame_storage_upload_intents_recovery_idx
  on public.beegame_storage_upload_intents (status, expires_at)
  where status in ('pending', 'uploading', 'verifying');

create table if not exists public.beegame_storage_migration_jobs (
  id uuid primary key default gen_random_uuid(),
  source_storage_object_id uuid not null references public.beegame_storage_objects(id) on delete restrict,
  destination_storage_object_id uuid not null references public.beegame_storage_objects(id) on delete restrict,
  status text not null default 'queued' check (status in ('queued', 'copying', 'verifying', 'ready_to_cutover', 'cutover_complete', 'source_deleted', 'copy_failed', 'verification_failed', 'cutover_failed', 'delete_source_failed')),
  attempts integer not null default 0 check (attempts >= 0),
  last_error text,
  started_at timestamptz,
  verified_at timestamptz,
  cutover_at timestamptz,
  source_deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint beegame_storage_migration_jobs_distinct_objects check (
    source_storage_object_id <> destination_storage_object_id
  ),
  unique (source_storage_object_id, destination_storage_object_id)
);

create index if not exists beegame_storage_migration_jobs_work_idx
  on public.beegame_storage_migration_jobs (status, updated_at);

alter table public.beegame_resource_packs
  add column if not exists cover_storage_object_id uuid references public.beegame_storage_objects(id) on delete set null;

alter table public.beegame_resource_elements
  add column if not exists storage_object_id uuid references public.beegame_storage_objects(id) on delete set null;

alter table public.beegame_deployments
  add column if not exists manifest_storage_object_id uuid references public.beegame_storage_objects(id) on delete set null;

alter table public.beegame_storage_objects enable row level security;
alter table public.beegame_storage_upload_intents enable row level security;
alter table public.beegame_storage_migration_jobs enable row level security;

drop policy if exists "storage object owner read" on public.beegame_storage_objects;
create policy "storage object owner read" on public.beegame_storage_objects
  for select using (
    owner_user_id = auth.uid()
    or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
    or public.beegame_is_platform_owner()
  );

drop policy if exists "storage object owner insert" on public.beegame_storage_objects;
create policy "storage object owner insert" on public.beegame_storage_objects
  for insert with check (
    owner_user_id = auth.uid()
    and (
      (scope_type = 'user' and scope_id = auth.uid()::text)
      or (scope_type = 'project' and project_id is not null and exists (
        select 1 from public.beegame_projects project
        where project.id = beegame_storage_objects.project_id
          and project.owner_id = auth.uid()
      ))
      or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
      or (scope_type = 'deployment' and deployment_id is not null and exists (
        select 1 from public.beegame_deployments deployment
        where deployment.id = beegame_storage_objects.deployment_id
          and deployment.owner_id = auth.uid()
      ))
      or (scope_type = 'session' and session_id is not null and exists (
        select 1 from public.beegame_sessions session
        where session.id = beegame_storage_objects.session_id
          and session.owner_id = auth.uid()
      ))
      or (scope_type in ('studio', 'platform') and public.beegame_is_platform_owner())
    )
  );

drop policy if exists "storage object owner update" on public.beegame_storage_objects;
create policy "storage object owner update" on public.beegame_storage_objects
  for update using (
    owner_user_id = auth.uid()
    or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
    or public.beegame_is_platform_owner()
  ) with check (
    public.beegame_is_platform_owner()
    or (
      owner_user_id = auth.uid()
      and (
        (scope_type = 'user' and scope_id = auth.uid()::text)
        or (scope_type = 'project' and project_id is not null and exists (
          select 1 from public.beegame_projects project
          where project.id = beegame_storage_objects.project_id
            and project.owner_id = auth.uid()
        ))
        or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
        or (scope_type = 'deployment' and deployment_id is not null and exists (
          select 1 from public.beegame_deployments deployment
          where deployment.id = beegame_storage_objects.deployment_id
            and deployment.owner_id = auth.uid()
        ))
        or (scope_type = 'session' and session_id is not null and exists (
          select 1 from public.beegame_sessions session
          where session.id = beegame_storage_objects.session_id
            and session.owner_id = auth.uid()
        ))
      )
    )
  );

drop policy if exists "storage upload intent owner access" on public.beegame_storage_upload_intents;
create policy "storage upload intent owner access" on public.beegame_storage_upload_intents
  for all using (owner_user_id = auth.uid() or public.beegame_is_platform_owner())
  with check (
    (owner_user_id = auth.uid() or public.beegame_is_platform_owner())
    and exists (
      select 1 from public.beegame_storage_objects object
      where object.id = storage_object_id
        and (object.owner_user_id = auth.uid() or public.beegame_is_platform_owner())
    )
  );

-- Migration jobs are a service/admin concern. Authenticated end users can see
-- only jobs for objects they own, while writes use a scoped backend service.
drop policy if exists "storage migration owner read" on public.beegame_storage_migration_jobs;
create policy "storage migration owner read" on public.beegame_storage_migration_jobs
  for select using (
    public.beegame_is_platform_owner()
    or exists (
      select 1 from public.beegame_storage_objects source
      where source.id = source_storage_object_id and source.owner_user_id = auth.uid()
    )
  );

revoke all on table public.beegame_storage_objects from anon;
revoke all on table public.beegame_storage_upload_intents from anon;
revoke all on table public.beegame_storage_migration_jobs from anon;
grant select, insert, update on table public.beegame_storage_objects to authenticated;
grant select, insert, update on table public.beegame_storage_upload_intents to authenticated;
grant select on table public.beegame_storage_migration_jobs to authenticated;
-- END SOURCE: beegame-storage-r2-foundation-migration.sql

-- BEGIN SOURCE: beegame-storage-r2-rls-hardening-migration.sql
-- Apply after beegame-storage-r2-foundation-migration.sql.
-- This narrows authenticated writes to business objects owned by auth.uid().

drop policy if exists "storage object owner insert" on public.beegame_storage_objects;
create policy "storage object owner insert" on public.beegame_storage_objects
  for insert with check (
    owner_user_id = auth.uid()
    and (
      (scope_type = 'user' and scope_id = auth.uid()::text)
      or (scope_type = 'project' and project_id is not null and exists (
        select 1 from public.beegame_projects project
        where project.id = beegame_storage_objects.project_id
          and project.owner_id = auth.uid()
      ))
      or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
      or (scope_type = 'deployment' and deployment_id is not null and exists (
        select 1 from public.beegame_deployments deployment
        where deployment.id = beegame_storage_objects.deployment_id
          and deployment.owner_id = auth.uid()
      ))
      or (scope_type = 'session' and session_id is not null and exists (
        select 1 from public.beegame_sessions session
        where session.id = beegame_storage_objects.session_id
          and session.owner_id = auth.uid()
      ))
      or (scope_type in ('studio', 'platform') and public.beegame_is_platform_owner())
    )
  );

drop policy if exists "storage object owner update" on public.beegame_storage_objects;
create policy "storage object owner update" on public.beegame_storage_objects
  for update using (
    owner_user_id = auth.uid()
    or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
    or public.beegame_is_platform_owner()
  ) with check (
    public.beegame_is_platform_owner()
    or (
      owner_user_id = auth.uid()
      and (
        (scope_type = 'user' and scope_id = auth.uid()::text)
        or (scope_type = 'project' and project_id is not null and exists (
          select 1 from public.beegame_projects project
          where project.id = beegame_storage_objects.project_id
            and project.owner_id = auth.uid()
        ))
        or (scope_type = 'pack' and pack_id is not null and public.beegame_can_manage_resource_pack(pack_id))
        or (scope_type = 'deployment' and deployment_id is not null and exists (
          select 1 from public.beegame_deployments deployment
          where deployment.id = beegame_storage_objects.deployment_id
            and deployment.owner_id = auth.uid()
        ))
        or (scope_type = 'session' and session_id is not null and exists (
          select 1 from public.beegame_sessions session
          where session.id = beegame_storage_objects.session_id
            and session.owner_id = auth.uid()
        ))
      )
    )
  );
-- END SOURCE: beegame-storage-r2-rls-hardening-migration.sql

-- BEGIN SOURCE: beegame-resource-pack-primary-category-migration.sql
-- Adds the resource Pack primary category contract without changing categories or elements.

alter table public.beegame_resource_packs
  add column if not exists primary_category text;

update public.beegame_resource_packs
set primary_category = case
  when (
    select count(distinct category.value)
    from jsonb_array_elements_text(
      case when jsonb_typeof(categories) = 'array' then categories else '[]'::jsonb end
    ) as category(value)
    where category.value in ('ui', 'audio', 'fonts', 'vfx', 'scenes')
  ) = 1
  then case
    when categories ? 'ui' then 'ui-kit'
    when categories ? 'audio' then 'audio'
    when categories ? 'fonts' then 'fonts'
    when categories ? 'vfx' then 'vfx'
    when categories ? 'scenes' then 'world-scene'
  end
  else 'mixed'
end
where primary_category is null;

alter table public.beegame_resource_packs
  alter column primary_category set default 'mixed',
  alter column primary_category set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'beegame_resource_packs_primary_category_check'
      and conrelid = 'public.beegame_resource_packs'::regclass
  ) then
    alter table public.beegame_resource_packs
      add constraint beegame_resource_packs_primary_category_check
      check (primary_category in ('2d-art', '3d-assets', 'animation-rig', 'ui-kit', 'vfx', 'audio', 'fonts', 'world-scene', 'mixed'));
  end if;
end
$$;
-- END SOURCE: beegame-resource-pack-primary-category-migration.sql

-- BEGIN SOURCE: beegame-resource-pack-catalog-migration.sql
begin;

alter table public.beegame_resource_packs
  add column if not exists styles text[] not null default '{}';

drop view if exists public.beegame_resource_pack_catalog;

alter table public.beegame_resource_packs
  drop column if exists style;

create view public.beegame_resource_pack_catalog
with (security_invoker = true)
as
with selectable_elements as (
  select e.*
  from public.beegame_resource_elements e
  where e.status = 'ready'
    and e.usage_tags_mode = 'override'
    and cardinality(e.usage_tags) > 0
    and e.asset_kind is not null
    and length(coalesce(e.specs ->> 'contentHash', '')) = 64
    and not exists (
      select 1
      from jsonb_array_elements_text(e.dependencies) dependency_id
      left join public.beegame_resource_elements dependency
        on dependency.id = dependency_id
      where dependency.id is null or dependency.status <> 'ready'
    )
    and not exists (
      select 1
      from jsonb_array_elements(e.dependency_bindings) binding
      left join public.beegame_resource_elements dependency
        on dependency.id = binding ->> 'dependencyElementId'
      where dependency.id is null or dependency.status <> 'ready'
    )
    and not exists (
      select 1
      from jsonb_array_elements(e.relations) relation
      left join public.beegame_resource_elements target
        on target.id = relation ->> 'targetElementId'
      where coalesce(relation ->> 'required', 'true') = 'true'
        and (target.id is null or target.status <> 'ready')
    )
)
select
  p.id as pack_id,
  p.version as pack_version,
  p.name as pack_name,
  p.styles,
  array(select jsonb_array_elements_text(p.game_types)) as game_types,
  p.dimension,
  p.primary_category,
  coalesce(array_agg(distinct e.category) filter (where e.id is not null), '{}') as categories,
  coalesce(p.tags, '{}') as tags,
  count(e.id)::integer as ready_element_count,
  coalesce(array_agg(distinct e.asset_kind) filter (where e.asset_kind is not null), '{}') as asset_kinds,
  coalesce(array(select distinct unnest(e2.usage_tags) from selectable_elements e2 where e2.pack_id = p.id), '{}') as usage_tags,
  coalesce(array(select distinct unnest(e3.capabilities) from selectable_elements e3 where e3.pack_id = p.id), '{}') as capabilities,
  coalesce(array_agg(distinct lower(reverse(split_part(reverse(e.path), '.', 1)))) filter (where e.id is not null and e.path like '%.%'), '{}') as formats,
  p.description,
  p.license,
  p.author,
  p.source,
  coalesce(p.compatible_engines, '{}') as compatible_engines
from public.beegame_resource_packs p
left join selectable_elements e on e.pack_id = p.id
where p.status = 'published'
group by p.id;

commit;
-- END SOURCE: beegame-resource-pack-catalog-migration.sql

-- BEGIN SOURCE: beegame-realtime-usage-bigint-migration.sql
-- Realtime usage can exceed PostgreSQL int4 during a single long-running
-- generation, especially when cached input tokens are included. Existing
-- installations created before the realtime billing schema used int4 for
-- some of these columns, so CREATE TABLE IF NOT EXISTS does not upgrade them.

alter table if exists public.beegame_usage_events
  alter column prompt_tokens type bigint using prompt_tokens::bigint,
  alter column completion_tokens type bigint using completion_tokens::bigint,
  alter column cache_read_tokens type bigint using cache_read_tokens::bigint,
  alter column cache_creation_tokens type bigint using cache_creation_tokens::bigint,
  alter column total_tokens type bigint using total_tokens::bigint,
  alter column prompt_tokens_delta type bigint using prompt_tokens_delta::bigint,
  alter column completion_tokens_delta type bigint using completion_tokens_delta::bigint,
  alter column cache_read_tokens_delta type bigint using cache_read_tokens_delta::bigint,
  alter column cache_creation_tokens_delta type bigint using cache_creation_tokens_delta::bigint,
  alter column total_tokens_delta type bigint using total_tokens_delta::bigint,
  alter column weighted_tokens type bigint using weighted_tokens::bigint,
  alter column weighted_tokens_delta type bigint using weighted_tokens_delta::bigint,
  alter column credits_micro type bigint using credits_micro::bigint;

alter table if exists public.beegame_usage_wallets
  alter column included_credits_micro type bigint using included_credits_micro::bigint,
  alter column consumed_credits_micro type bigint using consumed_credits_micro::bigint;

alter table if exists public.beegame_usage_debit_events
  alter column amount_credits_micro type bigint using amount_credits_micro::bigint;
-- END SOURCE: beegame-realtime-usage-bigint-migration.sql

-- BEGIN SOURCE: beegame-admin-permissions-migration.sql
-- Align the Supabase owner permission contract with the BeeGame API.
-- Safe to run repeatedly.

create or replace function public.beegame_role_permissions(role_name text)
returns text[]
language sql
security definer
set search_path = public
stable
as $$
  select case role_name
    when 'owner' then array[
      'workspace.read',
      'workspace.manage',
      'workspace.manage_members',
      'project.read',
      'project.create',
      'project.delete',
      'project.export',
      'agent.send_message',
      'agent.cancel',
      'agent.approve_tool',
      'preview.manage',
      'deployment.manage',
      'assets.upload',
      'assets.integrate',
      'model_config.manage',
      'mcp.manage',
      'skills.manage',
      'runtime_settings.manage',
      'secrets.manage',
      'credits.admin',
      'lifecycle.admin',
      'audit.read'
    ]
    when 'developer' then array[
      'workspace.read',
      'project.read',
      'project.create',
      'project.export',
      'agent.send_message',
      'agent.cancel',
      'agent.approve_tool',
      'preview.manage',
      'deployment.manage',
      'assets.upload',
      'assets.integrate',
      'skills.manage'
    ]
    when 'reviewer' then array[
      'workspace.read',
      'project.read',
      'project.export',
      'skills.manage'
    ]
    else array[
      'workspace.read',
      'project.read',
      'skills.manage'
    ]
  end
$$;

revoke execute on function public.beegame_role_permissions(text) from public;
grant execute on function public.beegame_role_permissions(text) to authenticated;
grant execute on function public.beegame_role_permissions(text) to service_role;
-- END SOURCE: beegame-admin-permissions-migration.sql

